if (made) game.banner = { text: "Caixas de Natal na região!", sub: `${made} presente${made > 1 ? "s" : ""} escondido${made > 1 ? "s" : ""} pela rua · podem ter a Pistola Natalina e Gorros de Natal`, t: 3600, gold: true };
