ctx.fillStyle = "#4a4b46"; for (const p of world.paths) ctx.fillRect(X(p.x), Y(p.y), p.w * k, p.h * k);
ctx.fillStyle = "#2f4a2a"; for (const t of world.trees) circle(X(t.x), Y(t.y), Math.max(1.5, t.r * k * 0.8));
